export default function LampadaCard({ lampada, onToggle, onDelete }) {
  const { id, nome, ligada } = lampada;

  return (
    <div className={`p-4 rounded-lg shadow-md transition-all ${ligada ? 'bg-yellow-100 border-l-8 border-yellow-500' : 'bg-white'}`}>
      <div className="flex justify-between items-center">
        <h3 className="text-xl font-semibold">{nome}</h3>
        <div className="flex gap-2">
          <button
            onClick={() => onToggle(id)}
            className={`px-3 py-1 rounded-md ${ligada ? 'bg-gray-500 hover:bg-gray-600' : 'bg-green-500 hover:bg-green-600'} text-white`}
          >
            {ligada ? 'Desligar' : 'Ligar'}
          </button>
          <button
            onClick={() => onDelete(id)}
            className="bg-red-500 hover:bg-red-600 text-white px-3 py-1 rounded-md"
          >
            Excluir
          </button>
        </div>
      </div>
      <p className="text-sm mt-2">Status: {ligada ? '🔆 Ligada' : '💡 Desligada'}</p>
    </div>
  );
}
